// RespostaCacheService.cs -- cache-aside para resposta de IA, reaproveitando
// o mesmo grupo de replicacao Multi-AZ do L13. O que muda e o dominio da
// chave e o TTL, que dependem do TIPO de conteudo, nao de um catalogo so.

public sealed class RespostaCacheService
{
    private readonly IConnectionMultiplexer _redis;

    // TTL por tipo de conteudo -- a mesma pergunta do L13 ("quanto tempo voce
    // tolera estar errado"), respondida diferente para cada dominio.
    private static readonly Dictionary<TipoConteudo, TimeSpan> TtlPorTipo = new()
    {
        [TipoConteudo.PoliticaInterna] = TimeSpan.FromHours(6),   // muda raramente
        [TipoConteudo.ContextoProduto] = TimeSpan.FromMinutes(15), // muda todo dia
        [TipoConteudo.ClassificacaoTicket] = TimeSpan.FromMinutes(2), // quase nunca repete
    };

    public RespostaCacheService(IConnectionMultiplexer redis) => _redis = redis;

    public async Task<string?> ObterAsync(string pergunta, TipoConteudo tipo)
    {
        var chave = ChaveNormalizada(pergunta, tipo);
        var db = _redis.GetDatabase();
        var valor = await db.StringGetAsync(chave);
        return valor.HasValue ? valor.ToString() : null; // null = MISS, chama o Bedrock
    }

    public async Task GravarAsync(string pergunta, TipoConteudo tipo, string resposta)
    {
        var chave = ChaveNormalizada(pergunta, tipo);
        var db = _redis.GetDatabase();
        await db.StringSetAsync(chave, resposta, TtlPorTipo[tipo]);
    }

    // Normalizacao SIMPLES: minusculas, espacos redundantes fora, pontuacao
    // fora. Nao junta perguntas com o MESMO SENTIDO e texto diferente -- essa
    // limitacao e conhecida e esta na secao de decisoes, nao escondida.
    private static string ChaveNormalizada(string pergunta, TipoConteudo tipo)
    {
        var normalizada = Regex.Replace(pergunta.Trim().ToLowerInvariant(), @"[^\w\s]|\s+", " ").Trim();
        var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(normalizada)))[..16];
        return $"ia:{tipo}:{hash}";
    }
}

public enum TipoConteudo { PoliticaInterna, ContextoProduto, ClassificacaoTicket }

// RoteadorDeModelo.cs -- mapeamento deterministico de tarefa para modelo.
// NAO e um modelo decidindo qual modelo usar: e uma tabela versionada,
// testavel com o golden set antes de qualquer mudanca ir para producao.

public sealed class RoteadorDeModelo
{
    private static readonly Dictionary<TipoTarefa, string> ModeloPorTarefa = new()
    {
        // Classificacao curta: modelo leve, medido no golden set antes de rotear
        // trafego real -- diferenca de acuracia medida em 0,6 ponto percentual
        // contra o modelo caro, dentro da margem aceita pelo time de suporte.
        [TipoTarefa.ClassificarTicket] = "amazon.nova-micro-v1:0",

        // Geracao longa com contexto do RAG: modelo potente, com cachePoint no
        // contexto recuperado -- ver ConverseComCache.
        [TipoTarefa.ResponderComRag] = "anthropic.claude-sonnet-4-5-...",
    };

    public string ModeloPara(TipoTarefa tarefa)
    {
        // Tarefa nova, ainda nao mapeada, cai no modelo potente por seguranca --
        // e fica registrada para medicao antes de ganhar uma linha propria aqui.
        if (!ModeloPorTarefa.TryGetValue(tarefa, out var modelo))
        {
            _logger.LogWarning("Tarefa {Tarefa} sem modelo mapeado -- usando padrao", tarefa);
            return ModeloPorTarefa[TipoTarefa.ResponderComRag];
        }
        return modelo;
    }

    private readonly ILogger<RoteadorDeModelo> _logger;
    public RoteadorDeModelo(ILogger<RoteadorDeModelo> logger) => _logger = logger;
}

public enum TipoTarefa { ClassificarTicket, ResponderComRag }

# lote-produtos.tf -- o que E declaravel: buckets, papel, agendador. O job
# em si (CreateModelInvocationJob) e uma chamada de API, nao um recurso.

resource "aws_s3_bucket" "lote_ia" {
  bucket = "${var.projeto}-lote-descricao-produto"
}

resource "aws_s3_bucket_lifecycle_configuration" "lote_ia" {
  bucket = aws_s3_bucket.lote_ia.id
  rule {
    id     = "expirar-saida-processada"
    status = "Enabled"
    filter { prefix = "saida/" }
    # 30 dias bastam: a descricao gerada e promovida para o catalogo em
    # producao logo apos o job -- o objeto aqui e so o resultado bruto.
    expiration { days = 30 }
  }
}

resource "aws_iam_role" "bedrock_batch" {
  name = "${var.projeto}-bedrock-batch"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow", Action = "sts:AssumeRole"
      Principal = { Service = "bedrock.amazonaws.com" }
    }]
  })
}

# Resource especifico dos DOIS lados -- entrada e saida -- e nada alem deles.
data "aws_iam_policy_document" "bedrock_batch" {
  statement {
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.lote_ia.arn}/entrada/*"]
  }
  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.lote_ia.arn}/saida/*"]
  }
}

resource "aws_scheduler_schedule" "disparar_lote_produtos" {
  name       = "${var.projeto}-disparar-lote-produtos"
  group_name = "default"

  flexible_time_window { mode = "OFF" }
  # Fora do horario comercial -- o job nunca compete com a fila interativa,
  # e a janela de horas do modo batch cabe folgada de madrugada.
  schedule_expression = "cron(0 2 * * ? *)"

  target {
    arn      = aws_lambda_function.criar_job_lote.arn
    role_arn = aws_iam_role.scheduler_invoca_lambda.arn
  }
}

// CriarJobLote.cs -- dispara o CreateModelInvocationJob. Chamada de API,
// nao recurso do Terraform: nao ha 'destroy' que desfaca um job em andamento,
// e o job termina sozinho -- nao ha estado para o provedor rastrear.

public async Task<string> CriarJobAsync(CancellationToken ct)
{
    var request = new CreateModelInvocationJobRequest
    {
        JobName = $"descricao-produto-{DateTime.UtcNow:yyyyMMdd}",
        ModelId = "anthropic.claude-haiku-4-5-...", // tarefa curta, modelo leve tambem no lote
        RoleArn = _roleArn,
        InputDataConfig = new() { S3InputDataConfig = new() {
            S3Uri = $"s3://{_bucket}/entrada/" } },
        OutputDataConfig = new() { S3OutputDataConfig = new() {
            S3Uri = $"s3://{_bucket}/saida/" } },
    };

    var resposta = await _bedrock.CreateModelInvocationJobAsync(request, ct);
    _logger.LogInformation("Job de lote criado: {JobArn}, ~10 mil itens, janela de horas",
        resposta.JobArn);
    return resposta.JobArn;
}

# iam-bedrock.tf -- Resource especifico do ARN do modelo: o papel que
# classifica ticket NAO tem permissao de invocar o modelo potente.

data "aws_iam_policy_document" "invocar_modelo_leve" {
  statement {
    effect    = "Allow"
    actions   = ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"]
    resources = ["arn:aws:bedrock:${var.regiao}::foundation-model/amazon.nova-micro-v1:0"]
  }
}

data "aws_iam_policy_document" "invocar_modelo_potente" {
  statement {
    effect    = "Allow"
    actions   = ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"]
    resources = ["arn:aws:bedrock:${var.regiao}::foundation-model/anthropic.claude-sonnet-4-5-*"]
  }
}

